<?php require_once __DIR__.'/comman/auth.php'; $pageTitle="Posts & Updates"; require __DIR__.'/comman/header.php'; require __DIR__.'/comman/sidebar.php'; ?><div class="content-wrapper"><section class="content-header"><div class="container-fluid"><div class="row mb-2"><div class="col-sm-8"><h1><?=h($pageTitle)?></h1></div></div><?php if($flash):?><div class="alert alert-<?=h($flash[0])?>"><?=h($flash[1])?></div><?php endif;?></div></section><section class="content"><div class="container-fluid"><?php $posts=read_json(CMS_DATA.'/posts.json',[]);$games=read_json(SITE_ROOT.'/data/games.json',[]);if(isset($_GET['delete'])){if(!hash_equals(csrf(),$_GET['csrf']??''))die('Invalid request');$slug=slugify($_GET['delete']);$posts=array_values(array_filter($posts,fn($p)=>($p['slug']??'')!==$slug));write_json(CMS_DATA.'/posts.json',$posts);$dir=SITE_ROOT.'/posts/'.$slug;if(is_dir($dir)){foreach(glob($dir.'/*') as $f)@unlink($f);@rmdir($dir);}update_posts_index($posts);update_latest_post($posts);flash('success','Post deleted.');redirect_admin('posts.php');}if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$gs=slugify(post_str('gameSlug'));$sel=null;foreach($games as $gx){if(($gx['slug']??'')===$gs){$sel=$gx;break;}}$p=['title'=>post_str('title'),'slug'=>slugify(post_str('slug')?:post_str('title')),'date'=>post_str('date',date('Y-m-d')),'type'=>post_str('type','Article Update'),'author'=>post_str('author','YonoLootZone'),'description'=>post_str('description'),'excerpt'=>post_str('excerpt'),'image'=>safe_url(post_str('image')),'imageAlt'=>post_str('imageAlt'),'video'=>safe_url(post_str('video')),'content'=>$_POST['content']??'','gameSlug'=>$sel['slug']??'','gameName'=>$sel['name']??'','gamePageLink'=>$sel?game_page_url($sel):'','gameImage'=>$sel['image']??'','promoEnabled'=>bool_post('promoEnabled'),'promoCode'=>post_str('promoCode'),'promoReward'=>post_str('promoReward'),'promoMinDeposit'=>post_str('promoMinDeposit'),'promoExpiry'=>post_str('promoExpiry'),'promoTerms'=>post_str(