o game selected</option><?php foreach($games as $gx):?><option value="<?=h($gx['slug'])?>" <?=($editPost['gameSlug']??'')===$gx['slug']?'selected':''?>><?=h($gx['name'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Author</label><input class="form-control" name="author" value="<?=h($editPost['author']??'YonoLootZone')?>"></div><div class="form-group"><label>Meta Description</label><textarea class="form-control" name="description" maxlength="160" required><?=h($editPost['description']??'')?></textarea></div><div class="form-group"><label>Excerpt</label><input class="form-control" name="excerpt" value="<?=h($editPost['excerpt']??'')?>"></div><div class="form-group"><label>Featured Image URL</label><input class="form-control" name="image" value="<?=h($editPost['image']??'')?>"></div><div class="form-group"><label>Image ALT</label><input class="form-control" name="imageAlt" value="<?=h($editPost['imageAlt']??'')?>"></div><div class="form-group"><label>Video URL</label><input class="form-control" name="video" value="<?=h($editPost['video']??'')?>"></div></div></div><div class="card card-outline card-warning"><div class="card-header"><h3 class="card-title">🎁 Promo Code</h3></div><div class="card-body"><div class="custom-control custom-checkbox mb-2"><input class="custom-control-input" id="promoEnabled" type="checkbox" name="promoEnabled" <?=!empty($editPost['promoEnabled'])?'checked':''?>><label class="custom-control-label" for="promoEnabled">Show promo code box</label></div><div class="row"><div class="col-md-3"><label>Code</label><input class="form-control" name="promoCode" value="<?=h($editPost['promoCode']??'')?>"></div><div class="col-md-3"><label>Reward / Offer</label><input class="form-control" name="promoReward" value="<?=h($editPost['promoReward']??'')?>"></div><div class="col-md-2"><label>Min Deposit</label><input class="form-control" name="promoMinDeposit" value="<?=h($editPost['promoMinDeposit']??'')?>"></div><div class="col-md-4"